public boolean whsLocationIsLPControlled()
{
    boolean ret = next whsLocationIsLPControlled();
    if ( this.LocProfileId )
    {
        ret = WHSLocationProfile::find(this.LocProfileId).lpControlled;
    }
    else if (!this.inventLocation().WHSEnabled)
    {
        ret = new MobDocLicensePlateOverview().parmEnableLicensePlating();
    }
    return ret;
}
